create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text not null unique,display_name text,avatar_url text,created_at timestamptz not null default now());
create table if not exists public.hackathons(id uuid primary key default gen_random_uuid(),host_id uuid not null references public.profiles(id) on delete cascade,name text not null,slug text,description text not null,theme text not null,category text not null,join_code text not null unique,status text not null default 'UPCOMING',registration_start timestamptz not null,registration_end timestamptz not null,hacking_start timestamptz not null,hacking_end timestamptz not null,submission_deadline timestamptz not null,judging_start timestamptz not null,judging_end timestamptz not null,winner_announcement_at timestamptz not null,max_team_size int not null default 4 check(max_team_size between 1 and 20),max_participants int check(max_participants between 1 and 100000),eligibility text,rules text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(registration_start<registration_end and registration_end<=hacking_start and hacking_start<hacking_end and hacking_end<=submission_deadline and submission_deadline<=judging_start and judging_start<judging_end and judging_end<=winner_announcement_at));
create table if not exists public.prizes(id uuid primary key default gen_random_uuid(),hackathon_id uuid not null references public.hackathons(id) on delete cascade,title text not null,position int,amount numeric not null default 0 check(amount>=0),currency text not null default 'INR',description text);
create table if not exists public.timeline_events(id uuid primary key default gen_random_uuid(),hackathon_id uuid not null references public.hackathons(id) on delete cascade,type text not null,title text not null,start_at timestamptz not null,end_at timestamptz not null,description text,check(end_at>=start_at));
create table if not exists public.hackathon_participants(id uuid primary key default gen_random_uuid(),hackathon_id uuid not null references public.hackathons(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,joined_at timestamptz not null default now(),status text not null default 'REGISTERED',unique(hackathon_id,user_id));
create table if not exists public.teams(id uuid primary key default gen_random_uuid(),hackathon_id uuid not null references public.hackathons(id) on delete cascade,name text not null,captain_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),unique(hackathon_id,name));
create table if not exists public.team_members(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.teams(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,joined_at timestamptz not null default now(),unique(team_id,user_id));
create table if not exists public.submissions(id uuid primary key default gen_random_uuid(),team_id uuid not null unique references public.teams(id) on delete cascade,project_name text not null,short_description text not null,description text,github_url text not null,demo_url text,video_url text,tech_stack text[] not null default '{}',status text not null default 'SUBMITTED',submitted_at timestamptz,updated_at timestamptz not null default now());
create table if not exists public.judges(id uuid primary key default gen_random_uuid(),hackathon_id uuid not null references public.hackathons(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),unique(hackathon_id,user_id));
create table if not exists public.judging_criteria(id uuid primary key default gen_random_uuid(),hackathon_id uuid not null references public.hackathons(id) on delete cascade,name text not null,max_score int not null check(max_score between 1 and 100),created_at timestamptz not null default now());
create table if not exists public.scores(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.submissions(id) on delete cascade,judge_id uuid not null references public.profiles(id) on delete cascade,innovation int not null check(innovation between 0 and 10),impact int not null check(impact between 0 and 10),technical int not null check(technical between 0 and 10),presentation int not null check(presentation between 0 and 10),comments text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(submission_id,judge_id));
create table if not exists public.winners(id uuid primary key default gen_random_uuid(),hackathon_id uuid not null references public.hackathons(id) on delete cascade,submission_id uuid not null references public.submissions(id) on delete cascade,prize_id uuid references public.prizes(id) on delete set null,rank int not null,announced_at timestamptz not null default now(),unique(hackathon_id,rank),unique(hackathon_id,submission_id));
create index if not exists hackathons_host_idx on public.hackathons(host_id);create index if not exists hackathons_code_idx on public.hackathons(join_code);create index if not exists participants_h_idx on public.hackathon_participants(hackathon_id);create index if not exists participants_u_idx on public.hackathon_participants(user_id);create index if not exists teams_h_idx on public.teams(hackathon_id);create index if not exists team_members_t_idx on public.team_members(team_id);create index if not exists team_members_u_idx on public.team_members(user_id);create index if not exists submissions_t_idx on public.submissions(team_id);create index if not exists scores_s_idx on public.scores(submission_id);create index if not exists judges_h_idx on public.judges(hackathon_id);
create or replace function public.make_join_code() returns text language plpgsql as $$declare c text;begin loop c=upper(substr(encode(gen_random_bytes(6),'hex'),1,7)); exit when not exists(select 1 from public.hackathons where join_code=c);end loop;return c;end$$;
create or replace function public.set_hackathon_code() returns trigger language plpgsql as $$begin if new.join_code is null or new.join_code='' then new.join_code=public.make_join_code();end if;return new;end$$;
drop trigger if exists hackathon_code_trigger on public.hackathons;create trigger hackathon_code_trigger before insert on public.hackathons for each row execute function public.set_hackathon_code();
create or replace function public.is_hackathon_host(hid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.hackathons h where h.id=hid and h.host_id=auth.uid())$$;
create or replace function public.is_hackathon_participant(hid uuid,uid uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.hackathon_participants p where p.hackathon_id=hid and p.user_id=uid)$$;
create or replace function public.create_team(p_hackathon_id uuid,p_name text) returns public.teams language plpgsql security definer set search_path=public as $$declare t public.teams;begin if not public.is_hackathon_participant(p_hackathon_id) then raise exception 'Join the hackathon first';end if;if exists(select 1 from public.team_members tm join public.teams t2 on t2.id=tm.team_id where t2.hackathon_id=p_hackathon_id and tm.user_id=auth.uid()) then raise exception 'You are already on a team';end if;insert into public.teams(hackathon_id,name,captain_id) values(p_hackathon_id,trim(p_name),auth.uid()) returning * into t;insert into public.team_members(team_id,user_id) values(t.id,auth.uid());return t;end$$;
create or replace function public.join_team(p_team_id uuid) returns public.team_members language plpgsql security definer set search_path=public as $$declare tm public.team_members; hid uuid; max_size int;begin select t.hackathon_id,h.max_team_size into hid,max_size from public.teams t join public.hackathons h on h.id=t.hackathon_id where t.id=p_team_id;if hid is null then raise exception 'Team not found';end if;if not public.is_hackathon_participant(hid) then raise exception 'Join the hackathon first';end if;if exists(select 1 from public.team_members tm2 join public.teams t2 on t2.id=tm2.team_id where t2.hackathon_id=hid and tm2.user_id=auth.uid()) then raise exception 'You are already on a team';end if;if (select count(*) from public.team_members where team_id=p_team_id)>=max_size then raise exception 'Team is full';end if;insert into public.team_members(team_id,user_id) values(p_team_id,auth.uid()) returning * into tm;return tm;end$$;
create or replace function public.submit_project(p_team_id uuid,p_project_name text,p_short_description text,p_description text,p_github_url text,p_demo_url text,p_video_url text,p_tech_stack text[]) returns public.submissions language plpgsql security definer set search_path=public as $$declare s public.submissions; hid uuid; deadline timestamptz;late boolean;begin select t.hackathon_id,h.submission_deadline into hid,deadline from public.teams t join public.hackathons h on h.id=t.hackathon_id where t.id=p_team_id and exists(select 1 from public.team_members tm where tm.team_id=t.id and tm.user_id=auth.uid());if hid is null then raise exception 'You are not a member of this team';end if;late=now()>deadline;if exists(select 1 from public.submissions where team_id=p_team_id) then raise exception 'A submission already exists for this team';end if;if late then raise exception 'Submission deadline has passed';end if;insert into public.submissions(team_id,project_name,short_description,description,github_url,demo_url,video_url,tech_stack,status,submitted_at) values(p_team_id,trim(p_project_name),trim(p_short_description),nullif(trim(p_description),''),trim(p_github_url),nullif(trim(p_demo_url),''),nullif(trim(p_video_url),''),p_tech_stack,'SUBMITTED',now()) returning * into s;return s;end$$;
create or replace view public.leaderboard as select s.id submission_id,t.hackathon_id,t.name team_name,s.project_name,coalesce(sum(sc.innovation+sc.impact+sc.technical+sc.presentation),0)::numeric total_score from public.submissions s join public.teams t on t.id=s.team_id left join public.scores sc on sc.submission_id=s.id group by s.id,t.hackathon_id,t.name,s.project_name;

alter table public.profiles enable row level security;alter table public.hackathons enable row level security;alter table public.prizes enable row level security;alter table public.timeline_events enable row level security;alter table public.hackathon_participants enable row level security;alter table public.teams enable row level security;alter table public.team_members enable row level security;alter table public.submissions enable row level security;alter table public.judges enable row level security;alter table public.judging_criteria enable row level security;alter table public.scores enable row level security;alter table public.winners enable row level security;
create policy profiles_read on public.profiles for select to authenticated using(true);create policy profiles_self_insert on public.profiles for insert to authenticated with check(id=auth.uid());create policy profiles_self_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy hackathons_read on public.hackathons for select to authenticated using(true);create policy hackathons_insert on public.hackathons for insert to authenticated with check(host_id=auth.uid());create policy hackathons_update on public.hackathons for update to authenticated using(host_id=auth.uid()) with check(host_id=auth.uid());create policy hackathons_delete on public.hackathons for delete to authenticated using(host_id=auth.uid());
create policy prizes_read on public.prizes for select to authenticated using(true);create policy prizes_host_write on public.prizes for all to authenticated using(public.is_hackathon_host(hackathon_id)) with check(public.is_hackathon_host(hackathon_id));
create policy timeline_read on public.timeline_events for select to authenticated using(true);create policy timeline_host_write on public.timeline_events for all to authenticated using(public.is_hackathon_host(hackathon_id)) with check(public.is_hackathon_host(hackathon_id));
create policy participant_read on public.hackathon_participants for select to authenticated using(true);create policy participant_self_insert on public.hackathon_participants for insert to authenticated with check(user_id=auth.uid());create policy participant_self_delete on public.hackathon_participants for delete to authenticated using(user_id=auth.uid() or public.is_hackathon_host(hackathon_id));create policy participant_host_update on public.hackathon_participants for update to authenticated using(public.is_hackathon_host(hackathon_id)) with check(public.is_hackathon_host(hackathon_id));
create policy teams_read on public.teams for select to authenticated using(true);create policy teams_host_write on public.teams for all to authenticated using(public.is_hackathon_host(hackathon_id)) with check(public.is_hackathon_host(hackathon_id));
create policy team_members_read on public.team_members for select to authenticated using(true);create policy team_members_self_delete on public.team_members for delete to authenticated using(user_id=auth.uid() or public.is_hackathon_host((select hackathon_id from public.teams where id=team_id))); 
create policy submissions_read on public.submissions for select to authenticated using(true);create policy submissions_host_update on public.submissions for update to authenticated using(public.is_hackathon_host((select hackathon_id from public.teams where id=team_id))) with check(public.is_hackathon_host((select hackathon_id from public.teams where id=team_id)));
create policy judges_read on public.judges for select to authenticated using(true);create policy judges_host_write on public.judges for all to authenticated using(public.is_hackathon_host(hackathon_id)) with check(public.is_hackathon_host(hackathon_id));
create policy criteria_read on public.judging_criteria for select to authenticated using(true);create policy criteria_host_write on public.judging_criteria for all to authenticated using(public.is_hackathon_host(hackathon_id)) with check(public.is_hackathon_host(hackathon_id));
create policy scores_read on public.scores for select to authenticated using(true);create policy scores_self_insert on public.scores for insert to authenticated with check(judge_id=auth.uid() and exists(select 1 from public.judges j where j.user_id=auth.uid() and j.id=judge_id));create policy scores_self_update on public.scores for update to authenticated using(judge_id=auth.uid()) with check(judge_id=auth.uid());
create policy winners_read on public.winners for select to authenticated using(true);create policy winners_host_write on public.winners for all to authenticated using(public.is_hackathon_host(hackathon_id)) with check(public.is_hackathon_host(hackathon_id));
